NEW_FILES = {'packages/preview/import_gate.py': '"""A walk preview is playable only once Godot has imported it, and the walk says so or fails.\n\nGodot loads a project\'s models, textures and their collision through its import cache, and only an editor or an\n``--import`` pass fills it: a Godot launched to PLAY a fresh project loads none of what is missing -- in the walker\'s\nwords on the first windowed run of the authoring loop, 2026-10-26, "fell through the floor of the first building i\nwalked in". That walk\'s headless import was killed at its 600 s timeout with 96 of 758 imports unwritten, every\nbuilding\'s shell among them, and the walk printed a warning and finished ``ok`` (the factory\'s\n`docs/findings/walk_2026-10-26_panel/`, L1).\n\nSo the import is judged by what it left, not by the process: `missing_imports` reads every ``.import`` sidecar and\nasks whether the cache file it names exists, which is the measurement that found the 96. `import_preview` runs the\npass, with the light bake\'s bound for importing the same package (`light_bake.IMPORT_TIMEOUT_S`), and answers\n``(ok, said)``; a timeout, a non-zero exit or any import left unwritten is not ok.\n"""\nfrom __future__ import annotations\n\nimport re\nimport subprocess\nfrom pathlib import Path\n\n_DEST = re.compile(r\'^(?:path|path\\.[A-Za-z0-9_]+)="(res://\\.godot/imported/[^"]+)"\', re.M)\n\n\ndef missing_imports(project: Path) -> list[str]:\n    """Every ``.import`` sidecar under ``project`` (outside ``.godot``) whose imported file is missing, as paths\n    relative to the project. A sidecar that names no imported file (``valid=false``, a skipped type) is not one."""\n    project = Path(project)\n    out = []\n    for sidecar in sorted(project.rglob("*.import")):\n        rel = sidecar.relative_to(project)\n        if rel.parts and rel.parts[0] == ".godot":\n            continue\n        dests = _DEST.findall(sidecar.read_text(encoding="utf-8", errors="replace"))\n        if dests and not all((project / d[len("res://"):]).exists() for d in dests):\n            out.append(rel.as_posix())\n    return out\n\n\ndef import_preview(godot_exe: str, project: Path, *, run=subprocess.run, timeout: float | None = None) -> tuple[bool, str]:\n    """Run Godot\'s headless ``--import`` on ``project`` and judge it by what it left. ``(ok, said)``."""\n    from packages.exporting.light_bake import IMPORT_TIMEOUT_S\n    timeout = IMPORT_TIMEOUT_S if timeout is None else timeout\n    try:\n        done = run([godot_exe, "--headless", "--path", str(project), "--import"], capture_output=True,\n                   timeout=timeout)\n    except subprocess.TimeoutExpired:\n        why = "the headless import did not finish in %d s" % timeout\n    except (OSError, subprocess.SubprocessError) as exc:\n        why = "the headless import could not run: %s" % exc\n    else:\n        why = "" if done.returncode == 0 else "the headless import exited %d" % done.returncode\n    missing = missing_imports(project)\n    if missing:\n        why = "%s%s of the preview\'s imports were not written (e.g. %s)" % (\n            (why + "; ") if why else "", len(missing), ", ".join(missing[:3]))\n    if why:\n        return False, why\n    return True, "imported: resources ready (headless --import pass, every import written)"\n', 'tests/unit/test_walk_import_gate.py': '"""A walk whose preview did not finish importing fails, and says why (0.257.0).\n\nThe walker fell through the floor of the first building they walked into: the walk\'s headless import had been killed\nat 600 s with 96 of 758 imports unwritten, every building\'s shell among them, and the walk finished ``ok`` (the\nfactory\'s docs/findings/walk_2026-10-26_panel/, L1). The import is now judged by what it left. FAILS ON 0.256.0.\n"""\nimport subprocess\nimport sys\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(ROOT))\n\nfrom packages.preview import import_gate  # noqa: E402\n\n\ndef _project(tmp_path, written):\n    """A project with two imports; ``written`` of their cache files exist."""\n    p = tmp_path / "preview"\n    (p / ".godot" / "imported").mkdir(parents=True)\n    for i, name in enumerate(("shell.glb", "brick.png")):\n        dest = ".godot/imported/%s-abc.scn" % name\n        (p / (name + ".import")).write_text(\'[remap]\\nimporter="x"\\npath="res://%s"\\n\' % dest, encoding="utf-8")\n        if i < written:\n            (p / dest).write_text("x", encoding="utf-8")\n    (p / "skipped.txt.import").write_text("[remap]\\nvalid=false\\n", encoding="utf-8")\n    return p\n\n\ndef _ok(argv, **kw):\n    return SimpleNamespace(returncode=0)\n\n\ndef test_an_import_that_wrote_everything_is_ok(tmp_path):\n    ok, said = import_gate.import_preview("godot", _project(tmp_path, 2), run=_ok)\n    assert ok and "every import written" in said\n\n\ndef test_unwritten_imports_fail_and_are_named(tmp_path):\n    p = _project(tmp_path, 1)\n    assert import_gate.missing_imports(p) == ["brick.png.import"]\n    ok, said = import_gate.import_preview("godot", p, run=_ok)\n    assert not ok and "1 of the preview\'s imports were not written" in said and "brick.png.import" in said\n\n\ndef test_a_timeout_is_a_failure_and_the_light_bakes_bound_is_used(tmp_path):\n    from packages.exporting.light_bake import IMPORT_TIMEOUT_S\n    seen = {}\n\n    def slow(argv, **kw):\n        seen["timeout"] = kw["timeout"]\n        raise subprocess.TimeoutExpired(argv, kw["timeout"])\n    ok, said = import_gate.import_preview("godot", _project(tmp_path, 1), run=slow)\n    assert not ok and "did not finish in %d s" % IMPORT_TIMEOUT_S in said\n    assert seen["timeout"] == IMPORT_TIMEOUT_S == 1800\n\n\ndef test_a_failing_exit_is_a_failure_even_with_everything_written(tmp_path):\n    ok, said = import_gate.import_preview("godot", _project(tmp_path, 2),\n                                          run=lambda argv, **kw: SimpleNamespace(returncode=3))\n    assert not ok and "exited 3" in said\n\n\ndef test_the_walk_blocks_on_a_failed_import(tmp_path, monkeypatch):\n    """`cmd_walk` stops with EXIT_BLOCKED and a BLOCKED line, before the self-check, when the gate says no."""\n    from apps.cli import commands\n    src = (ROOT / "apps" / "cli" / "commands" / "__init__.py").read_text(encoding="utf-8")\n    walk = src[src.index("def cmd_walk("):]\n    walk = walk[:walk.index("\\ndef ", 1)]\n    assert "import_gate.import_preview(" in walk and "return EXIT_BLOCKED" in walk.split("import_gate.import_preview(")[1][:900]\n    assert "headless import failed" not in walk                       # the warning that let it through is gone\n    assert commands.EXIT_BLOCKED == 2\n', 'apps/godot/README.md': "# The Gabagool Factory authoring project\n\nOpen this folder in Godot 4.7 and the Factory panel appears in the right-hand dock. It finds the factory by walking\nup from here (`docs/AUTHORING_LOOP.md` at the factory root says what the panel does and how far it has got).\n\n`project.godot` is committed in the format the Godot editor writes, so opening and closing the project leaves the\nrepository unchanged. Its first lines are the editor's own header; this file carries what used to head it.\n\n`tests/` holds the panel's headless tests:\n\n    godot --headless --path <this folder> --script res://tests/<test>.gd\n"}
CHANGELOG = '## [0.257.0] - a walk whose preview did not finish importing fails, and says why\n\n### Fixed\n- **A failed import no longer passes the walk.** The walker, on the first windowed run of the authoring loop\n  (2026-10-26): "fell through the floor of the first building i walked in".\n  - The walk\'s headless `--import` had been killed at its 600 s timeout with 96 of 758 imports unwritten, every\n    building\'s shell among them. A Godot opening a project to play does not import, so those meshes and their\n    collision never loaded.\n  - The walk printed a warning and finished ok; the panel said "walk it and see". The code\'s own comment named the\n    consequence ("invisible walls over live collision, dead ladders") and still only warned (the factory\'s\n    `docs/findings/walk_2026-10-26_panel/`, L1).\n  - **`packages/preview/import_gate.py`** judges the import by what it left. `missing_imports` reads every `.import`\n    sidecar and asks whether the cache file it names exists, the measurement that found the 96. `import_preview`\n    runs the pass with the light bake\'s bound for importing the same package (`light_bake.IMPORT_TIMEOUT_S`,\n    1,800 s, was 600). A timeout, a non-zero exit or any import left unwritten is not ok.\n  - `walk` stops with `BLOCKED: the walk preview is not playable: ...` and `EXIT_BLOCKED`, before the self-check.\n    The panel\'s walk error quotes that line instead of "the preview exited 2".\n- **Opening the authoring project no longer dirties the repository.** The Godot editor rewrites `project.godot` in\n  its own format on save, and did the first time the walker closed it. The file is committed in that format; the note\n  that headed it is in `apps/godot/README.md`.\n\n### Tests\n- `tests/unit/test_walk_import_gate.py` (fails on 0.256.0):\n  - a complete import is ok;\n  - an unwritten import fails and is named;\n  - a timeout fails at the light bake\'s 1,800 s bound;\n  - a failing exit fails even with everything written;\n  - `walk` returns `EXIT_BLOCKED` on the gate and the old warning is gone.\n\n'
OLD_VERSION, NEW_VERSION = '0.256.0', '0.257.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
